insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000000631', 'should', 'ʃʊd', 'modal verb', 'deveria', 'You should see a doctor.', 'Você deveria ver um médico.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000632', 'shouldn''t', 'ˈʃʊdnt', 'modal verb', 'não deveria', 'You shouldn''t work so much.', 'Você não deveria trabalhar tanto.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000633', 'advice', 'ədˈvaɪs', 'noun', 'conselho', 'Can you give me some advice?', 'Você pode me dar um conselho?', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000634', 'to advise', 'tuː ədˈvaɪz', 'verb', 'aconselhar', 'I advise you to rest.', 'Eu te aconselho a descansar.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000635', 'why don''t you', 'waɪ doʊnt juː', 'phrase', 'por que você não', 'Why don''t you try again?', 'Por que você não tenta de novo?', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000636', 'if I were you', 'ɪf aɪ wɜːr juː', 'phrase', 'se eu fosse você', 'If I were you, I would wait.', 'Se eu fosse você, eu esperaria.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000637', 'to recommend', 'tuː ˌrekəˈmend', 'verb', 'recomendar', 'I recommend this restaurant.', 'Eu recomendo esse restaurante.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000638', 'recommendation', 'ˌrekəmenˈdeɪʃn', 'noun', 'recomendação', 'Thanks for the recommendation.', 'Obrigado pela recomendação.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000639', 'to warn', 'tuː wɔːrn', 'verb', 'avisar / alertar', 'I warned you about this.', 'Eu te avisei sobre isso.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000640', 'to solve', 'tuː sɒlv', 'verb', 'resolver', 'How can I solve this problem?', 'Como posso resolver esse problema?', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000641', 'problem', 'ˈprɒbləm', 'noun', 'problema', 'I have a problem at work.', 'Eu tenho um problema no trabalho.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000642', 'solution', 'səˈluːʃn', 'noun', 'solução', 'There is no easy solution.', 'Não há uma solução fácil.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000643', 'to consider', 'tuː kənˈsɪdər', 'verb', 'considerar', 'You should consider all options.', 'Você deveria considerar todas as opções.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000644', 'option', 'ˈɒpʃn', 'noun', 'opção', 'You have two options.', 'Você tem duas opções.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000645', 'to deal with', 'tuː diːl wɪð', 'verb', 'lidar com', 'I don''t know how to deal with this.', 'Eu não sei como lidar com isso.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000646', 'to give up', 'tuː ɡɪv ʌp', 'verb', 'desistir', 'Don''t give up now.', 'Não desista agora.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000647', 'to try again', 'tuː traɪ əˈɡen', 'verb', 'tentar de novo', 'Just try again tomorrow.', 'Só tente de novo amanhã.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000648', 'better idea', 'ˈbetər aɪˈdɪə', 'noun', 'ideia melhor', 'I have a better idea.', 'Eu tenho uma ideia melhor.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000649', 'to be worried', 'tuː biː ˈwʌrid', 'verb', 'estar preocupado', 'I''m worried about my exam.', 'Eu estou preocupado com minha prova.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000650', 'don''t worry', 'doʊnt ˈwʌri', 'phrase', 'não se preocupe', 'Don''t worry, everything will be fine.', 'Não se preocupe, tudo vai ficar bem.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000651', 'to make a decision', 'tuː meɪk ə dɪˈsɪʒn', 'verb', 'tomar uma decisão', 'I need to make a decision soon.', 'Eu preciso tomar uma decisão logo.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000652', 'to be worth it', 'tuː biː wɜːrθ ɪt', 'phrase', 'valer a pena', 'It''s hard, but it''s worth it.', 'É difícil, mas vale a pena.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000653', 'to take a break', 'tuː teɪk ə breɪk', 'verb', 'fazer uma pausa', 'You should take a break.', 'Você deveria fazer uma pausa.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000654', 'point of view', 'pɔɪnt ʌv vjuː', 'noun', 'ponto de vista', 'From my point of view, it''s a good idea.', 'Do meu ponto de vista, é uma boa ideia.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000655', 'to be honest', 'tuː biː ˈɒnɪst', 'phrase', 'para ser sincero', 'To be honest, I don''t agree.', 'Para ser sincero, eu não concordo.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000656', 'to make sense', 'tuː meɪk sens', 'verb', 'fazer sentido', 'That advice makes sense.', 'Esse conselho faz sentido.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000657', 'to be right', 'tuː biː raɪt', 'verb', 'estar certo', 'I think you''re right.', 'Eu acho que você está certo.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000658', 'to be wrong', 'tuː biː rɒŋ', 'verb', 'estar errado', 'Maybe I''m wrong about this.', 'Talvez eu esteja errado sobre isso.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000659', 'mistake', 'mɪˈsteɪk', 'noun', 'erro', 'Everyone makes mistakes.', 'Todo mundo comete erros.', 'A2', array['advice']),
('30000000-0000-0000-0000-000000000660', 'to learn from', 'tuː lɜːrn frɒm', 'verb', 'aprender com', 'You can learn from your mistakes.', 'Você pode aprender com seus erros.', 'A2', array['advice']);
